import Scene from "./Scene";

const fixture: SceneResult = {
  place: "café",
  task: { fr: "commande un café", en: "order a coffee", role: "serveur" },
  objects: [
    {
      id: "o1",
      fr: "la tasse",
      en: "the cup",
      article: "la",
      gender: "f",
